  body.split(/(<w:tbl\b|<\/w:tbl>)/).forEach(function (part) {
    if (part === "<w:tbl") { depth++; return; }
    if (part === "</w:tbl>") { depth = Math.max(0, depth - 1); return; }
    (part.match(/<w:p\b[\s\S]*?<\/w:p>|<w:p\b[^>]*\/>/g) || []).forEach(function (p) {
      var ppr = (/<w:pPr>[\s\S]*?<\/w:pPr>/.exec(p) || [""])[0];
      var style = (/<w:pStyle w:val="([^"]+)"/.exec(ppr) || [])[1] || "";
      var lvl = /<w:numPr>/.test(ppr) ? Number((/<w:ilvl w:val="(\d+)"/.exec(ppr) || [0, 0])[1]) : -1;
      var t = text(p);
      if (!t) return;
      var runs = p.match(/<w:r\b[\s\S]*?<\/w:r>/g) || [], boldRuns = runs.filter(function (r) { return /<w:b\/>|<w:b w:val="(?:1|true|on)"\/>/.test(r) && /<w:t/.test(r); }).length;
      out.push({ text: t, style: style, level: lvl, numbered: lvl >= 0, bold: runs.length > 0 && boldRuns * 2 > runs.filter(function (r) { return /<w:t/.test(r); }).length, inTable: depth > 0 });
    });
