  T.forEach(function (tc, ti) {
    var h = norm(tc.heading), di = -1;
    if (h && h !== "opening") D.forEach(function (dc, k) { if (di < 0 && !usedD[k] && norm(dc.heading) === h) di = k; });
    if (di >= 0) { usedD[di] = 1; pairs.push({ t: ti, d: di, by: "heading" }); } else pairs.push({ t: ti, d: -1, by: "" });
  });
  pairs.forEach(function (pr) {
    if (pr.d >= 0) return;
    var tb = bag(T[pr.t].text + " " + T[pr.t].heading), best = -1, bs = 0.5;
    D.forEach(function (dc, k) { if (usedD[k]) return; var o = overlap(tb, bag(dc.text + " " + dc.heading)); if (o > bs) { bs = o; best = k; } });
    if (best >= 0) { usedD[best] = 1; pr.d = best; pr.by = "wording"; }
  });
  var out = pairs.map(function (pr) {
    var tc = T[pr.t];
    if (pr.d < 0) return { t: pr.t, d: -1, heading: tc.heading, outcome: "removed", same: 0, confidence: tc.text.length > 40 ? "medium" : "low", added: 0, removed: 0, sample: [] };
    var dc = D[pr.d], w = W(tc.text, dc.text);
    // A template clause with alternative wording (tc.variable: both branches of an IF in it): unchanged when the
    // executed clause adds nothing to the template, whichever branch it kept.
    var outcome = (tc.variable ? w.added <= 3 : w.same >= 0.97 && w.added + w.removed <= 3) ? "unchanged" : "changed";
    var confidence = tc.variable ? "medium" : pr.by === "heading" ? (w.same >= 0.5 || outcome === "unchanged" ? "high" : "medium") : (w.same >= 0.75 ? "medium" : "low");
    return { t: pr.t, d: pr.d, heading: tc.heading, outcome: outcome, same: Math.round(w.same * 100) / 100, confidence: confidence, added: w.added, removed: w.removed, sample: outcome === "changed" ? w.sample : [] };
  });
  D.forEach(function (dc, k) {
    if (usedD[k] || dc.heading === "(opening)") return;
    out.push({ t: -1, d: k, heading: dc.heading, outcome: "added", same: 0, confidence: "medium", added: String(dc.text || "").split(/\s+/).filter(Boolean).length, removed: 0, sample: [] });
  });
  return out;
}

// ─── [PRECEDENT-DIGEST] Step 3: precedents as patterns Respond can send (offline parts, 10-20) ───
// precPartyTerm(preamble, name) — what the agreement calls the other party: "Example University (the “University”)"
// → "University"; "" when the opening doesn't say.

engine.precPartyTerm:
function precPartyTerm(preamble, name) {
  var s = String(preamble || ""), n = String(name || "");
  var at = n ? s.indexOf(n) : -1;
  if (at < 0) return "";
  var m = /^[^()]{0,200}?\((?:the\s+|hereinafter(?:\s+referred\s+to\s+as)?\s+)?["“]([^"”]{1,40})["”]\)/i.exec(s.slice(at + n.length));
  return m ? m[1].trim() : "";
}

// precDelta(sample, names) — a changed clause as its delta from Colgate's standard, digested when it's read:
// { kind: "insert" | "delete" | "replace" | "", ins, del, sample, scrubbed: true } — the words added and the words
// struck (each at most 40 words, as written where precWords kept them), and the sample to store. No names: emails,
// web addresses and phone numbers go, and each of names ([{ name, term }]) becomes its defined term, else "the other
// party".

engine.precDelta:
function precDelta(sample, names) {
  function scrub(t) {
    t = String(t || "").replace(/[\w.+-]+@[\w-]+\.[\w.-]+/g, "[email]").replace(/\bhttps?:\/\/\S+|\bwww\.\S+/gi, "[web address]")
      .replace(/\+?\(?\d[\d\s().-]{8,}\d/g, function (x) { return x.replace(/\D/g, "").length >= 10 ? "[phone]" : x; });
    (names || []).forEach(function (x) {
      var n = String((x && x.name) || "").trim();
      if (n.length < 3) return;
      t = t.replace(new RegExp(n.replace(/[.*+?^${}()|[\]\\]/g, "\\$&").replace(/\s+/g, "\\s+"), "gi"), (x && x.term) || "the other party");
    });
    return t;
  }
  function clip(t) { var w = String(t || "").split(/\s+/).filter(Boolean); return w.length > 40 ? w.slice(0, 40).join(" ") + " …" : w.join(" "); }
  var ins = [], del = [];
  (sample || []).forEach(function (r) { var x = r && (r.o != null ? r.o : r.t); if (x && (r.k === "ins" || r.k === "del")) (r.k === "ins" ? ins : del).push(x); });
  var I = clip(scrub(ins.join(" … "))), D = clip(scrub(del.join(" … ")));
  return { kind: I && D ? "replace" : I ? "insert" : D ? "delete" : "", ins: I, del: D, scrubbed: true,
    sample: (sample || []).map(function (r) { return { k: r.k, t: scrub(r.t) }; }) };
}

// precPatterns(records, opts) — the approved agreements as patterns, per clause (its taxonomy key: a general clause
// across agreement types, a type's own clause only for opts.type): how Colgate's standard fared and the deltas grouped
// by kind and wording, each with agreements, attorneys and counterparties (counts only — no initials, names or dates),
// its share of the agreements with that clause, and strength (rules: strongAttorneys 3, strongShare 0.7,
// strongCounterparties 2; one attorney or one agreement is SINGLE). An exemplar only from a delta digested without
// names (scrubbed). A clause holding others is an article (isArticle); each clause names its article. opts: { type,
// years (10), today, rules, mark (an agreement id: its patterns carry has, and was — the same without it), fields
// (precFields(): a pattern's name from its structured terms) }. Deals on different structured values never share a pattern.
// { agreements, keys: { key: { key, heading, general, article, isArticle, agreements,
// patterns: [{ kind: "kept" | "insert" | "delete" | "replace" | "removed" | "added", agreements, attorneys,
// counterparties, share, level, exemplar }] } } }

engine.precPatterns:
function precPatterns(records, opts) {
  opts = opts || {};
  var R = opts.rules || {}, SA = R.strongAttorneys || 3, SS = R.strongShare || 0.7, SC = R.strongCounterparties || 2;
  var years = opts.years || 10, today = String(opts.today || "9999-12-31"), cut = (Number(today.slice(0, 4)) - years) + today.slice(4);
  function words(t) { var o = {}; String(t || "").toLowerCase().split(/[^a-z0-9$%]+/).forEach(function (w) { if (w.length > 2) o[w] = 1; }); return o; }
  function overlap(a, b) {
    var ka = Object.keys(a), kb = Object.keys(b);
    if (!ka.length || !kb.length) return ka.length === kb.length ? 1 : 0;
    return ka.filter(function (k) { return b[k]; }).length / Math.max(ka.length, kb.length);
  }
  var keys = {}, n = 0, holds = {}, LBL = {}, UL = (opts.fields && opts.fields.units) || {};
  Object.keys((opts.fields && opts.fields.clauses) || {}).forEach(function (k) { opts.fields.clauses[k].forEach(function (f) { LBL[f.field] = f.label; }); });
  (records || []).forEach(function (r) {
    if (!r || r.status !== "approved" || r.include === false || (r.date && r.date < cut)) return;
    n++;
    (r.clauses || []).forEach(function (c) {
      if (!c || c.include === false || !c.clauseKey) return;
      if (!c.general && opts.type && r.agreementType !== opts.type) return;
      var e = keys[c.clauseKey] = keys[c.clauseKey] || { general: !!c.general, headings: {}, recs: {}, groups: [], arts: {} };
      e.headings[c.clauseType || ""] = (e.headings[c.clauseType || ""] || 0) + 1;
      e.recs[r.id] = 1;
      if (c.articleKey && c.articleKey !== c.clauseKey) { e.arts[c.articleKey] = (e.arts[c.articleKey] || 0) + 1; holds[c.articleKey] = 1; }
      var d = c.delta || {}, kind = c.outcome === "unchanged" ? "kept" : c.outcome === "removed" ? "removed" : c.outcome === "added" ? "added"
        : d.kind || (c.added && c.removed ? "replace" : c.added ? "insert" : c.removed ? "delete" : "replace");
      var ex = d.scrubbed ? (kind === "delete" ? d.del : d.ins) || "" : "", w = words(ex), g = null;
      // [PRECEDENT-STATS] its structured terms: deals on different values are different patterns
      var tv = {};
      (c.terms || []).forEach(function (t) { if (t && t.field && t.value != null) tv[t.field] = String(t.value) + (t.unit ? " " + t.unit : ""); });
      var fits = function (x) { return Object.keys(tv).every(function (f) { return !(f in x.tv) || x.tv[f] === tv[f]; }); };
      for (var i = 0; i < e.groups.length && !g; i++) {
        var x = e.groups[i];
        if (x.kind === kind && fits(x) && (!/^(insert|delete|replace)$/.test(kind) || Object.keys(tv).length || overlap(x.w, w) >= 0.5)) g = x;
      }
      if (!g) { g = { kind: kind, w: w, recs: {}, ex: "", exAt: "", tv: {}, kt: {} }; e.groups.push(g); }
      Object.keys(tv).forEach(function (f) { if (!(f in g.tv)) g.tv[f] = tv[f]; });
      (c.keyTerms || []).slice(0, 3).forEach(function (t) { g.kt[t] = (g.kt[t] || 0) + 1; });
      g.recs[r.id] = { ini: r.initials || "", par: r.partyHash || "" };
      if (ex && String(r.date || "") >= g.exAt) { g.ex = ex; g.exAt = String(r.date || ""); }   // the newest wording stands for its group
    });
  });
  var most = function (o) { return Object.keys(o).sort(function (a, b) { return o[b] - o[a]; })[0] || ""; };
  function stats(recs, total, skip) {
    var ids = Object.keys(recs).filter(function (id) { return id !== skip; }), att = {}, par = {};
    ids.forEach(function (id) { if (recs[id].ini) att[recs[id].ini] = 1; if (recs[id].par) par[recs[id].par] = 1; });
    var ag = ids.length, at = Object.keys(att).length, cp = Object.keys(par).length, share = total ? ag / total : 0;
    return { agreements: ag, attorneys: at, counterparties: cp, share: Math.round(share * 100) / 100,
      level: at <= 1 || ag <= 1 ? "single" : at >= SA && share >= SS && cp >= SC ? "strong" : "some" };
  }
  var out = { agreements: n, keys: {} };
  Object.keys(keys).forEach(function (k) {
    var e = keys[k], total = Object.keys(e.recs).length;
    out.keys[k] = { key: k, heading: most(e.headings), general: e.general, article: most(e.arts), isArticle: !!holds[k], agreements: total,
      patterns: e.groups.map(function (g) {
        var pt = Object.assign({ kind: g.kind }, stats(g.recs, total, null), { exemplar: /^(insert|delete|replace)$/.test(g.kind) ? g.ex : "" });
        // [PRECEDENT-STATS] named by substance: its terms ("review period 30 days"), else its commonest key term
        var nm = Object.keys(g.tv).map(function (f) { var p = g.tv[f].split(" "), u = p.length > 1 ? p.pop() : ""; return (LBL[f] || f.replace(/_/g, " ")) + " " + p.join(" ") + (UL[u] ? " " + UL[u] : u && !(u in UL) ? " " + u : ""); }).join("; ") || (g.kind !== "kept" ? most(g.kt) : "");
        if (nm) pt.name = nm;
        // [PRECEDENT-CARD] opts.mark: the pattern holding that agreement says so, and what it was without it
        if (opts.mark && g.recs[opts.mark]) { pt.has = true; pt.was = stats(g.recs, total - 1, opts.mark); }
        return pt;
      }).sort(function (a, b) { return b.agreements - a.agreements || b.attorneys - a.attorneys; }) };
  });
  return out;
}

// precPick(index, para, max) — at most max (2) patterns for one paragraph the other side changed: para { key, article,
// kind } (their change: "insert" | "delete" | "replace"; key / article: the index keys its heading and its article's
// heading matched). Only kinds that answer their change, never a SINGLE one; the paragraph's own clause before its
// article's (an article's patterns apply to every clause in it), strong before some, the closer kind, the larger share.
// [{ key, scope: "clause" | "article", heading, of (agreements with that clause), pattern, rank }]

engine.precPick:
function precPick(index, para, max) {
  var K = (index && index.keys) || {}, p = para || {}, out = [];
  var REL = { insert: { kept: 2, insert: 3, replace: 2, added: 1 }, delete: { kept: 2, delete: 3, replace: 2, removed: 3 },
    replace: { kept: 2, replace: 3, insert: 2, delete: 2 } }[p.kind] || {};
  [[p.key, "clause"], [p.article, "article"]].forEach(function (s) {
    var e = s[0] && Object.prototype.hasOwnProperty.call(K, s[0]) ? K[s[0]] : null;
    if (!e || (s[1] === "article" && (s[0] === p.key || !e.isArticle))) return;
    (e.patterns || []).forEach(function (pt) {
      if (pt.level === "single" || !REL[pt.kind]) return;
      out.push({ key: e.key, scope: s[1], heading: e.heading, of: e.agreements, pattern: pt,
        rank: (pt.level === "strong" ? 100 : 0) + (s[1] === "clause" ? 10 : 0) + REL[pt.kind] * 2 + pt.share });
    });
  });
  return out.sort(function (a, b) { return b.rank - a.rank; }).slice(0, max || 2);
}

// precLine(pick) — one pattern as its prompt line (about 30–60 tokens): what was done in how many of the agreements,
// by how many attorneys and counterparties (counts), its strength, and for a changed clause the wording to model a
// counter on. No names, no dates.

engine.precLine:
function precLine(x) {
  var pt = (x && x.pattern) || {}, of = " in " + pt.agreements + " of " + x.of + " executed agreements" + (pt.name && pt.kind !== "kept" ? " (" + pt.name + ")" : "");   // [PRECEDENT-STATS] its name
  var what = pt.kind === "kept" ? "Colgate's standard kept" + of
    : pt.kind === "removed" ? "the clause removed" + of
    : pt.kind === "added" ? "an added clause kept" + of
    : "changed" + of + (pt.kind === "delete" ? ", striking" : pt.kind === "insert" ? ", adding" : ", rewording to") + (pt.exemplar ? " “" + pt.exemplar + "”" : "");
  return (x.scope === "article" ? "article " + x.heading + ": " : "") + what + " (" + pt.attorneys + " attorney" + (pt.attorneys === 1 ? "" : "s") + ", " +
    pt.counterparties + " counterpart" + (pt.counterparties === 1 ? "y" : "ies") + ", " + String(pt.level || "").toUpperCase() + ")";
}

// precBudget(items, cap) — a run's precedent lines held to cap tokens (about 4 characters each, 1500 by default):
// items [{ id, lines: [{ text, rank }] }] (each paragraph's best first); over the cap every paragraph's best line goes
// before any second one, the higher rank first — one each for 50+ changed paragraphs. { lines: { id: [text] }, tokens, dropped }

engine.precBudget:
function precBudget(items, cap) {
  cap = cap || 1500;
  var all = [];
  (items || []).forEach(function (it) { (it.lines || []).forEach(function (l, i) { all.push({ id: it.id, i: i, text: String(l.text || ""), rank: +l.rank || 0 }); }); });
  all.sort(function (a, b) { return a.i - b.i || b.rank - a.rank; });
  var used = 0, keep = [], dropped = 0;
  all.forEach(function (l) {
    var t = Math.ceil((l.text.length + 4) / 4);
    if (used + t > cap) { dropped++; return; }
    used += t; keep.push(l);
  });
  var lines = {};
  keep.sort(function (a, b) { return a.i - b.i; }).forEach(function (l) { (lines[l.id] = lines[l.id] || []).push(l.text); });
  return { lines: lines, tokens: used, dropped: dropped };
}

// ─── [PRECEDENT-BULK] Bulk import: one AI call per agreement ──────────
// precAiPrompt(ctx) — the one call that reads an executed agreement (the PDF attached, scans too; or a Word file's
// text in ctx.text) against Colgate's template for its type. ctx: { types: [type ids], taxonomy: [keys], entities,
// template: { name, clauses: [{ heading, text }] } | null, text?, templateChars (24000) }. Asks for RAW JSON.

engine.precAiPrompt:
function precAiPrompt(ctx) {
  ctx = ctx || {};
  var budget = ctx.templateChars || 24000, used = 0, std = [];
  ((ctx.template && ctx.template.clauses) || []).forEach(function (c) {
    var line = "- " + String(c.heading || "").slice(0, 100) + ": " + String(c.text || "").replace(/\s+/g, " ").slice(0, 600);
    if (used + line.length > budget) return;
    used += line.length; std.push(line);
  });
  // [PRECEDENT-STATS] the structured terms each clause key records (ctx.fields: precFields())
  var F = (ctx.fields && ctx.fields.clauses) || {}, flist = Object.keys(F).map(function (k) { return k + ": " + F[k].map(function (f) { return f.field + " [" + f.units.join("|") + "]"; }).join(", "); }).join("; ");
  return [
    "You read ONE EXECUTED agreement (" + (ctx.text ? "its text is below" : "attached as a PDF — it may be a scan") + ") for Colgate's legal team, to record what was agreed compared with Colgate's own standard template. Return RAW JSON only.",
    "",
    "1. agreementType: one of " + JSON.stringify(ctx.types || []) + ", or \"Other\".",
    "2. counterpartyEntity: one of " + JSON.stringify(ctx.entities || ["university", "company", "hospital", "government", "nonprofit", "individual", "other"]) + ".",
    "3. counterpartyName: the other party's legal name as written (Colgate and its affiliates are never the other party).",
    "4. effectiveDate: YYYY-MM-DD — the agreement's own date, else the latest signature date; \"\" if none.",
    "4a. referenceNumber: Colgate's reference number, usually in the footer or header, like \"A-2025-8503-OC\"; \"\" if none.",
    "4b. term: the agreement's term as {\"value\": number, \"unit\": \"months\" | \"years\"}; null if it has none.",
    "4c. totalWords: about how many words the agreement has.",
    "5. clauses: every SUBSTANTIVE clause — anything that allocates rights, obligations, money, risk or time. Always include governing law, venue and disputes, insurance, liability, indemnity, confidentiality, intellectual property, publication, publicity, payment, term and termination, warranties, data protection, audit, assignment, compliance and survival when present. SKIP pure mechanics: the title, recitals, headings with no terms, counterparts, signature pages, notice addresses.",
    "   Each: {\"heading\": as written, \"key\": one of " + JSON.stringify(ctx.taxonomy || []) + " or \"other\", \"status\": \"same\" | \"changed\" | \"added\" | \"removed\", \"delta\": \"at most 40 words: what differs from Colgate's standard (\\\"\\\" when same)\", \"keyTerms\": [\"amounts, periods, caps, percentages — as written\"], \"quote\": \"8 to 20 words copied EXACTLY from this agreement's clause (\\\"\\\" for removed)\", \"terms\": [{\"field\", \"value\", \"unit\"}], \"words\": number, \"notUseful\": true | false, \"notUsefulWhy\": \"\"}",
    "   terms: the clause's structured terms in THIS agreement, from its key's list below — value a number (or short text for a choice or a jurisdiction), unit from the brackets; [] when none apply. Anything else stays in keyTerms.",
    "   words: how many words the clause has in this agreement (0 for removed).",
    "   notUseful: true when the outcome is no use as precedent — a one-off, deal-specific detail, or a wording change with no effect; notUsefulWhy: at most 12 words.",
    flist ? "   TERM FIELDS BY KEY: " + flist : null,
    "   same = substantively Colgate's standard wording; changed = the same clause on different terms; added = a clause Colgate's standard doesn't have; removed = a clause in Colgate's standard that this agreement doesn't have.",
    "",
    std.length ? "COLGATE'S STANDARD (" + String(ctx.template.name || "template") + "):\n" + std.join("\n")
      : "No Colgate template for this type: give status \"unknown\" for every clause and put its key terms in delta (at most 40 words).",
    ctx.text ? "\nTHE AGREEMENT:\n\"\"\"\n" + String(ctx.text).slice(0, 400000) + "\n\"\"\"" : "",
    "",
    "{\"agreementType\":\"\",\"counterpartyEntity\":\"\",\"counterpartyName\":\"\",\"effectiveDate\":\"\",\"referenceNumber\":\"\",\"term\":null,\"totalWords\":0,\"clauses\":[]}",
  ].filter(function (l) { return l !== null; }).join("\n");
}

// precAiParse(raw, ctx, keyFor) — the answer as a precedent record's facts and clauses, every field checked: a type
// from the list, an entity from the list, a real date; mechanics dropped by heading too; each clause on the taxonomy
// (the AI's key when it is one, else keyFor(heading, type) — precClauseKey, passed in); deltas, key terms and quotes
// clipped and scrubbed (emails, phones, web addresses; the other party's name → ctx.term || "the other party").
// ctx: { types, taxonomy, entities, scan, hasTemplate, fields (precFields()), termFn (precTerm), refFn (precRef) }.
// { agreementType, entityType, date, partyName, clauses (with terms, words, notUseful), ref, term, totalWords }

engine.precAiParse:
function precAiParse(raw, ctx, keyFor) {
  ctx = ctx || {};
  var o = raw && typeof raw === "object" ? raw : {}, name = String(o.counterpartyName || "").replace(/\s+/g, " ").trim().slice(0, 160);
  var types = ctx.types || [], tax = ctx.taxonomy || [], ents = ctx.entities || ["university", "company", "hospital", "government", "nonprofit", "individual", "other"];
  function scrub(t) {
    t = String(t || "").replace(/[\w.+-]+@[\w-]+\.[\w.-]+/g, "[email]").replace(/\bhttps?:\/\/\S+|\bwww\.\S+/gi, "[web address]")
      .replace(/\+?\(?\d[\d\s().-]{8,}\d/g, function (x) { return x.replace(/\D/g, "").length >= 10 ? "[phone]" : x; });
    var bare = name.replace(/,?\s+(?:inc|llc|l\.l\.c|ltd|limited|gmbh|corporation|corp|company|co)\.?$/i, "");
    [name, bare].forEach(function (n) { if (n.length >= 3) t = t.replace(new RegExp(n.replace(/[.*+?^${}()|[\]\\]/g, "\\$&").replace(/\s+/g, "\\s+"), "gi"), ctx.term || "the other party"); });
    return t.replace(/\s+/g, " ").trim();
  }
  function words(t, n) { var w = String(t || "").split(/\s+/).filter(Boolean); return w.length > n ? w.slice(0, n).join(" ") + " …" : w.join(" "); }
  var MECH = /^(?:\(opening\)|title|recitals?|background|preamble|whereas|witnesseth|in witness|signatures?|signature page|execution|counterparts?|notices? addresses?|addresses for notices|headings?)\b/i;
  var type = types.indexOf(o.agreementType) >= 0 ? o.agreementType : "";
  var date = /^\d{4}-\d{2}-\d{2}$/.test(String(o.effectiveDate || "")) && !isNaN(Date.parse(o.effectiveDate)) ? o.effectiveDate : "";
  var OUT = { same: "unchanged", changed: "changed", added: "added", removed: "removed", unknown: "unknown" };
  var clauses = (Array.isArray(o.clauses) ? o.clauses : []).map(function (c) {
    if (!c || typeof c !== "object") return null;
    var heading = String(c.heading || "").replace(/\s+/g, " ").trim().slice(0, 120), outcome = OUT[String(c.status || "").toLowerCase()];
    if (!heading || !outcome || MECH.test(heading)) return null;
    var k = tax.indexOf(c.key) >= 0 ? { key: c.key, general: true } : (typeof keyFor === "function" ? keyFor(heading, type) : { key: (type || "Unknown") + ": " + heading.toLowerCase(), general: false });
    var delta = words(scrub(c.delta), 40);
    var row = { clauseType: heading, clauseKey: k.key, general: !!k.general, outcome: outcome, detected: outcome, confidence: ctx.scan ? "medium" : "high",
      keyTerms: (Array.isArray(c.keyTerms) ? c.keyTerms : []).slice(0, 8).map(function (x) { return words(scrub(x), 8).slice(0, 60); }).filter(Boolean),
      quote: outcome === "removed" ? "" : words(String(c.quote || "").replace(/\s+/g, " ").trim(), 30), include: true, level: 0, article: "", articleKey: "",
      delta: outcome === "changed" && delta ? { kind: "replace", ins: delta, del: "", scrubbed: true } : outcome === "unknown" && delta ? { kind: "", ins: delta, del: "", scrubbed: true } : null };
    // [PRECEDENT-STATS] its structured terms, held to its key's list (one not on it a free key term); its length; the flag
    var list = ((ctx.fields && ctx.fields.clauses) || {})[k.key] || [];
    row.terms = [];
    (Array.isArray(c.terms) ? c.terms : []).slice(0, 8).forEach(function (t) {
      var got = typeof ctx.termFn === "function" ? ctx.termFn(t, list) : null;
      if (got) { if (!row.terms.some(function (x) { return x.field === got.field; })) row.terms.push(got); }
      else if (t && t.field && t.value != null && String(t.value).trim()) row.keyTerms.push(words(scrub(String(t.field).replace(/_/g, " ") + ": " + t.value + (t.unit ? " " + t.unit : "")), 8).slice(0, 60));
    });
    row.terms.forEach(function (t) { if (typeof t.value === "string") t.value = scrub(t.value); });
    row.words = Number(c.words) >= 0 && Number(c.words) < 50000 ? Math.round(Number(c.words)) : null;
    row.notUseful = c.notUseful === true;
    row.notUsefulWhy = row.notUseful ? words(scrub(c.notUsefulWhy), 12) : "";
    // Nothing to compare against (no template for the type): kept for later, out of the patterns until compared.
    if (outcome === "unknown" || ctx.hasTemplate === false) { row.include = false; row.skip = "no template to compare"; }
    return row;
  }).filter(Boolean);
  var term = o.term && typeof o.term === "object" && Number(o.term.value) > 0 && /^(months|years)$/.test(String(o.term.unit || "").toLowerCase()) ? { value: Number(o.term.value), unit: String(o.term.unit).toLowerCase() } : null;
  return { agreementType: type, entityType: ents.indexOf(o.counterpartyEntity) >= 0 ? o.counterpartyEntity : "", date: date, partyName: name, clauses: clauses,
    // [PRECEDENT-STATS] the reference held to its format (ctx.refFn: precRef), the term, the word count
    ref: typeof ctx.refFn === "function" ? ctx.refFn(o.referenceNumber) : null, term: term,
    totalWords: Number(o.totalWords) > 0 && Number(o.totalWords) < 2000000 ? Math.round(Number(o.totalWords)) : null };
}

// precAiGuard(clauses, text) — the accuracy guard for files with a text layer: every clause's quote must be in the
// agreement's own words (spacing, quotes, dashes and case aside). One that isn't is flagged and left out of the counts
// until the owner counts it back in. A scan (text "") can't be checked: marked as from a scan; a PDF pdf.js couldn't open
// (why "unread"): marked unchecked. { found, missing, scan, unchecked }

engine.precAiGuard:
function precAiGuard(clauses, text, why) {
  function norm(s) { return String(s || "").toLowerCase().replace(/[“”"«»]/g, "\"").replace(/[‘’`']/g, "'").replace(/[‐-―−]/g, "-").replace(/\s+/g, " ").replace(/\s+([,.;:)])/g, "$1").replace(/\(\s+/g, "(").trim(); }
  // [PRECEDENT-PDFJS] why "unread": a PDF pdf.js couldn't open — no text to check against, but not a scan.
  var hay = norm(text), unread = why === "unread", out = { found: 0, missing: 0, scan: !hay && !unread, unchecked: !hay && unread };
  (clauses || []).forEach(function (c) {
    if (c.outcome === "removed") return;
    if (!hay) { c.guard = unread ? "unchecked" : "scan"; return; }
    var q = norm(String(c.quote || "").replace(/\s*…$/, ""));
    if (q.length >= 12 && hay.indexOf(q) >= 0) { c.guard = "found"; out.found++; return; }
    c.guard = "missing"; c.include = false; c.confidence = "low"; c.skip = q ? "its words aren't in the agreement" : "no quote to check";
    out.missing++;
  });
  return out;
}

// precCost(docs, model) — before Start: what the batch will take. docs: [{ pages?, chars? }] (a PDF counts pages, a Word
// file its text); about 258 tokens a PDF page, 4 characters a token, the prompt and template, and the answer with its
// thinking. Prices per million tokens as ELI's usage report has them (eli_telemetry etEstimateCost). Three at a time,
// about 35 s each. { documents, pages, inTokens, outTokens, usd, minutes, model }

engine.precCost:
function precCost(docs, model) {
  var PRICES = { "gemini-3.1-flash-lite-preview": [0.04, 0.2], "gemini-3.1-flash": [0.075, 0.3], "gemini-2.5-flash": [0.075, 0.3], "gemini-2.5-pro": [1.25, 5],
    "gemini-flash-lite-latest": [0.04, 0.2], "gemini-flash-latest": [0.075, 0.3], _default: [0.075, 0.3] };
  var D = docs || [], pages = 0, inTok = 0, outTok = 0;
  D.forEach(function (d) {
    var p = Number(d && d.pages) || 0, c = Number(d && d.chars) || 0;
    pages += p;
    inTok += (p ? p * 258 : Math.ceil(c / 4)) + 7000;   // the document; the prompt and Colgate's template
    outTok += 2600;                                    // the answer (about 30 clauses) and its thinking
  });
  var pr = PRICES[model] || PRICES._default;
  return { documents: D.length, pages: pages, inTokens: inTok, outTokens: outTok, usd: Math.round((inTok * pr[0] + outTok * pr[1]) / 1e6 * 1000) / 1000,
    minutes: Math.max(1, Math.ceil(D.length * 35 / 3 / 60)), model: model || "" };
}

// precInitialsFromName(name, known) — the attorney's initials from a file's name: "[AN]" / "(AN)" anywhere, or a
// leading "AN - " / "AN_" when AN is a known attorney; never a document acronym (NDA, MSA, SOW …). "" when none.

engine.precInitialsFromName:
function precInitialsFromName(name, known) {
  var N = String(name || "").replace(/\.(pdf|docx)$/i, ""), K = (known || []).map(function (x) { return String(x).toUpperCase(); });
  var SKIP = /^(NDA|CDA|MSA|MTA|SOW|SLA|DPA|LOI|MOU|CRA|CTA|PO|POA|IP|USA|UK|EU|LLC|INC|LTD|CP|HPN|UIC|VCU|PDF|DOC|AMD|AMEND)$/;
  var m = /[\[(]([A-Z]{2,3})[\])]/.exec(N);
  if (m && !SKIP.test(m[1])) return m[1];
  m = /^([A-Z]{2,3})(?:\s*[-–_]\s*|\s+)/.exec(N);
  if (m && !SKIP.test(m[1]) && K.indexOf(m[1]) >= 0) return m[1];
  return "";
}

