// precExpectMs(kind, size, hist) — about how long one AI read takes, in ms: a PDF by its pages, a Word file by its
// characters; from this computer's past reads of that kind (hist: [[size, ms]], the latest 20) when it has any.

engine.precExpectMs:
function precExpectMs(kind, size, hist) {
  var n = Math.max(1, Number(size) || 1), H = (hist || []).filter(function (h) { return h && h[0] > 0 && h[1] > 0; });
  if (H.length) { var s = 0, m = 0; H.forEach(function (h) { s += h[0]; m += h[1]; }); return Math.max(10000, Math.round(m / s * n)); }
  return kind === "pdf" ? 12000 + 2500 * n : 12000 + Math.round(n / 1000) * 400;
}

// [PRECEDENT-CARD] precPreview(records, agr, opts, patterns, line) — how one agreement would show as precedent if approved
// now (patterns, line: precPatterns and precLine — engine functions don't see each other in a bundle):
// precPatterns over the approved records with it (its type; opts: { today, rules, years }). Per counted clause (by index):
// the pattern it joins or starts, its counts and strength now and before, and the line Respond's AI would read (precLine;
// none while SINGLE — precPick never offers one). { clauses: { i: { fresh, kind, agreements, of, attorneys,
// counterparties, level, was, line } }, summary: { counted, joins, starts, seen, up } }

engine.precPreview:
function precPreview(records, agr, opts, patterns, line) {
