  var rows = (records || []).filter(function (r) { return r && r.id !== id; }).concat([mine]);
  var idx = patterns(rows, { type: mine.agreementType || "", today: opts.today, rules: opts.rules, years: opts.years, mark: id, fields: opts.fields });
  var out = { clauses: {}, summary: { counted: 0, joins: 0, starts: 0, seen: 0, up: 0 } }, S = out.summary;
