}

// [PRECEDENT-CARD] precScrub(text, names, max) — the owner's own words for a clause's change, held to the same rules as
// the AI's: no email, web address or phone number, the other party's name (and its bare form) as "the other party",
// at most max words (40). names: [{ name, term? }].

engine.precScrub:
function precScrub(text, names, max) {
  var t = String(text || "").replace(/[\w.+-]+@[\w-]+\.[\w.-]+/g, "[email]").replace(/\bhttps?:\/\/\S+|\bwww\.\S+/gi, "[web address]")
    .replace(/\+?\(?\d[\d\s().-]{8,}\d/g, function (x) { return x.replace(/\D/g, "").length >= 10 ? "[phone]" : x; });
  (names || []).forEach(function (x) {
    var n = String((x && x.name) || "").trim(), bare = n.replace(/,?\s+(?:inc|llc|l\.l\.c|ltd|limited|gmbh|corporation|corp|company|co)\.?$/i, "");
    [n, bare].forEach(function (v) { if (v.length >= 3) t = t.replace(new RegExp(v.replace(/[.*+?^${}()|[\]\\]/g, "\\$&").replace(/\s+/g, "\\s+"), "gi"), (x && x.term) || "the other party"); });
  });
  var w = t.split(/\s+/).filter(Boolean);
  return w.slice(0, max || 40).join(" ");
}

