// precRef(text) — Colgate's reference number in text, a footer or a file name ("A-2025-8503-OC": a letter, the year,
// the sequence, the category code; spaces and any dash or underscore between) as { ref, year, seq, cat }, or null.
// The category is the code's last letters, as the Auto Emailer reads it.

engine.precRef:
function precRef(text) {
  var m = /(?:^|[^A-Z0-9])([A-Z])\s?[-_‐-―−]\s?((?:19|20)\d\d)\s?[-_‐-―−]\s?(\d{3,7})\s?[-_‐-―−]\s?([A-Z]{2,3})(?![A-Z0-9])/.exec(String(text || "").toUpperCase());
